/* Keep business handlers and native form controls intact during component migration. */
(function(){let installed=false;window.addEventListener('bpd-design-ready',()=>{if(installed)return;installed=true;const ui=window.BPDDesignRuntime,oldBtn=btn,oldBadge=badge,oldField=field,oldArea=area;btn=function(label,action,primary=false){return ui.buttonMarkup(oldBtn(label,action,primary),primary)};badge=function(value){return ui.badgeMarkup(oldBadge(value))};field=function(){return ui.fieldMarkup(oldField.apply(this,arguments))};area=function(){return ui.fieldMarkup(oldArea.apply(this,arguments))};if(typeof authUser!=='undefined'&&authUser&&!journey&&!choosingBranch&&!document.querySelector('#modal')?.open)renderContent();ui.refresh()})})();
